        loan = self.loans.get(book_id)
        if loan is None or loan.user != user:
            raise ValueError(f"User {user} has not borrowed book {book_id}.")

        del self.loans[book_id]
        self.user_books[user].remove(book_id)

        due_date = loan.borrow_date + timedelta(days=self.loan_days)
        delay_days = self._count_overdue_business_days(due_date, day)

        fine = delay_days * self.daily_fine
        if fine > 0:
            self.fines[user] += fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines[user]

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self.fines.pop(user, None)

    @staticmethod
    def _count_overdue_business_days(due_date: date, return_date: date) -> int:
        """Count weekdays (Monday through Friday) strictly after due_date up to return_date."""
        overdue_days = (return_date - due_date).days
        if overdue_days <= 0:
            return 0

        return sum(
            1
            for offset in range(1, overdue_days + 1)
            if (due_date + timedelta(days=offset)).weekday() < 5
        )
